INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Carbohydrate Metabolism','easy','mcq','Which enzyme catalyzes the irreversible conversion of phosphoenolpyruvate (PEP) to pyruvate in the final step of glycolysis?','["A. Pyruvate kinase","B. Phosphoglycerate kinase","C. Enolase","D. Phosphoglycerate mutase"]','A','Pyruvate kinase catalyzes the final irreversible step of glycolysis, converting PEP to pyruvate with net ATP production by substrate-level phosphorylation. It is allosterically activated by fructose-1,6-bisphosphate and inhibited by ATP and alanine.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Carbohydrate Metabolism','medium','mcq','A 2-year-old presents with fasting hypoglycemia, hepatomegaly, and lactic acidosis. Liver biopsy shows accumulation of glucose-6-phosphate. Which enzyme is most likely deficient?','["A. Glycogen phosphorylase","B. Glucose-6-phosphatase","C. Phosphoglucomutase","D. Glucokinase"]','B','Glucose-6-phosphatase deficiency causes Von Gierke disease (GSD type Ia). Without this enzyme, glucose-6-phosphate cannot be converted to free glucose, leading to hypoglycemia, hepatomegaly from glycogen accumulation, and lactic acidosis from increased glycolysis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Carbohydrate Metabolism','medium','mcq','Which of the following is the rate-limiting enzyme of the TCA cycle and is allosterically inhibited by NADH and ATP?','["A. Citrate synthase","B. Alpha-ketoglutarate dehydrogenase","C. Isocitrate dehydrogenase","D. Malate dehydrogenase"]','C','Isocitrate dehydrogenase catalyzes the first oxidative decarboxylation in the TCA cycle and is considered the rate-limiting enzyme. It is allosterically activated by ADP and Ca2+ and inhibited by NADH and ATP, linking cycle activity to cellular energy status.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Carbohydrate Metabolism','medium','mcq','During gluconeogenesis, which enzyme bypasses the irreversible pyruvate kinase step by converting pyruvate to oxaloacetate?','["A. Phosphoenolpyruvate carboxykinase (PEPCK)","B. Glucose-6-phosphatase","C. Fructose-1,6-bisphosphatase","D. Pyruvate carboxylase"]','D','Pyruvate carboxylase converts pyruvate to oxaloacetate in the mitochondria, using biotin as a cofactor and requiring ATP. This is the first committed step of gluconeogenesis, bypassing the irreversible pyruvate kinase reaction. It is activated by acetyl-CoA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Carbohydrate Metabolism','hard','mcq','In the pentose phosphate pathway, which enzyme generates NADPH and is critical for maintaining reduced glutathione in red blood cells?','["A. Glucose-6-phosphate dehydrogenase","B. Transaldolase","C. Transketolase","D. Phosphogluconate dehydrogenase"]','A','Glucose-6-phosphate dehydrogenase (G6PD) is the rate-limiting enzyme of the pentose phosphate pathway and the primary source of NADPH in red blood cells. G6PD deficiency impairs regeneration of reduced glutathione, making RBCs vulnerable to oxidative hemolysis triggered by drugs such as primaquine and dapsone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Carbohydrate Metabolism','medium','mcq','Which of the following correctly describes the net ATP yield from the complete aerobic oxidation of one molecule of glucose?','["A. 2 ATP","B. 30-32 ATP","C. 8 ATP","D. 38 ATP"]','B','The complete aerobic oxidation of glucose yields approximately 30-32 ATP by current estimates. This accounts for 2 ATP from glycolysis, 2 GTP from the TCA cycle, and approximately 26-28 ATP from oxidative phosphorylation driven by the NADH and FADH2 produced.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Carbohydrate Metabolism','medium','mcq','A patient with chronic alcohol use develops confusion and ophthalmoplegia. Laboratory studies show elevated pyruvate. Which enzyme of carbohydrate metabolism is most directly impaired?','["A. Pyruvate carboxylase","B. Lactate dehydrogenase","C. Pyruvate dehydrogenase complex","D. Phosphofructokinase-1"]','C','The pyruvate dehydrogenase complex (PDH) requires thiamine pyrophosphate (TPP) as a cofactor. Chronic alcohol use causes thiamine (vitamin B1) deficiency, impairing PDH activity. Pyruvate accumulates and is converted to lactate and alanine. This underlies Wernicke-Korsakoff syndrome.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Carbohydrate Metabolism','easy','mcq','Phosphofructokinase-1 (PFK-1), the rate-limiting enzyme of glycolysis, is allosterically activated by which of the following?','["A. ATP and citrate","B. Glucagon and cAMP","C. Glucose-6-phosphate and alanine","D. AMP and fructose-2,6-bisphosphate"]','D','PFK-1 is activated by AMP, ADP, and fructose-2,6-bisphosphate, and inhibited by ATP and citrate. Fructose-2,6-bisphosphate is the most potent allosteric activator of PFK-1 and is produced by PFK-2, which is activated in the fed state by insulin signalling.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Carbohydrate Metabolism','hard','mcq','In glycogen synthesis, which nucleotide sugar is the direct glucosyl donor for glycogen synthase?','["A. UDP-glucose","B. GDP-glucose","C. ADP-glucose","D. CDP-glucose"]','A','Glycogen synthase transfers glucose from UDP-glucose to the growing glycogen chain via alpha-1,4-glycosidic bonds. UDP-glucose is formed from glucose-1-phosphate and UTP by UDP-glucose pyrophosphorylase. The branching enzyme creates alpha-1,6-glycosidic bonds at branch points.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Carbohydrate Metabolism','medium','mcq','Which of the following amino acids can serve as a purely glucogenic substrate, entering the TCA cycle as succinyl-CoA after undergoing odd-chain propionyl-CoA processing?','["A. Leucine","B. Valine","C. Lysine","D. Phenylalanine"]','B','Valine (along with isoleucine and threonine) is catabolized to propionyl-CoA, which is carboxylated to methylmalonyl-CoA (by propionyl-CoA carboxylase, requiring biotin and vitamin B12) and then converted to succinyl-CoA. Succinyl-CoA is a TCA intermediate and hence glucogenic. Leucine and lysine are purely ketogenic. Phenylalanine is both glucogenic and ketogenic.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Lipid Metabolism','easy','mcq','Which enzyme is the rate-limiting step in cholesterol biosynthesis and the target of statin drugs?','["A. HMG-CoA reductase","B. Acetyl-CoA carboxylase","C. HMG-CoA synthase","D. Squalene synthase"]','A','HMG-CoA reductase catalyzes the conversion of HMG-CoA to mevalonate, which is the committed and rate-limiting step in cholesterol synthesis. Statins are competitive inhibitors of this enzyme and are the most widely prescribed drugs for lowering LDL cholesterol.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Lipid Metabolism','medium','mcq','A patient presents with fasting hyperketonemia. Which of the following correctly describes ketone body synthesis (ketogenesis)?','["A. It occurs in the cytoplasm of hepatocytes","B. It produces acetoacetate, beta-hydroxybutyrate, and acetone","C. It is stimulated by insulin and inhibited by glucagon","D. It uses succinyl-CoA as the primary substrate"]','B','Ketogenesis occurs in hepatocyte mitochondria during fasting, prolonged exercise, and diabetic ketoacidosis. The ketone bodies produced are acetoacetate, beta-hydroxybutyrate, and acetone. The pathway is stimulated by high acetyl-CoA from fatty acid oxidation when oxaloacetate is depleted by gluconeogenesis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Lipid Metabolism','medium','mcq','Which lipoprotein is responsible for transporting cholesterol from peripheral tissues back to the liver (reverse cholesterol transport)?','["A. Chylomicrons","B. VLDL","C. HDL","D. LDL"]','C','HDL (high-density lipoprotein) mediates reverse cholesterol transport by accepting free cholesterol from peripheral tissues via ATP-binding cassette transporter A1 (ABCA1). Cholesterol is esterified by LCAT and transported to the liver for excretion. High HDL is cardioprotective.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Lipid Metabolism','medium','mcq','During beta-oxidation of a 16-carbon saturated fatty acid (palmitate), how many acetyl-CoA molecules are produced?','["A. 6","B. 7","C. 9","D. 8"]','D','Beta-oxidation of palmitate (C16:0) requires 7 cycles, each removing a 2-carbon acetyl-CoA unit, ultimately yielding 8 acetyl-CoA molecules, 7 NADH, and 7 FADH2. The formula is n/2 acetyl-CoA for an n-carbon saturated fatty acid.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Lipid Metabolism','hard','mcq','Which vitamin-derived cofactor is required for the carboxylation step catalyzed by acetyl-CoA carboxylase in fatty acid synthesis?','["A. Biotin","B. Pyridoxal phosphate","C. Thiamine pyrophosphate","D. Cobalamin"]','A','Acetyl-CoA carboxylase catalyzes the rate-limiting step of fatty acid synthesis, converting acetyl-CoA to malonyl-CoA using biotin as a prosthetic group to carry the CO2. This reaction requires ATP and is activated by citrate and insulin, and inhibited by palmitoyl-CoA and glucagon.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Lipid Metabolism','medium','mcq','A 45-year-old man with severe hypertriglyceridemia has markedly reduced activity of lipoprotein lipase (LPL). Which lipoprotein would accumulate most in his plasma?','["A. HDL","B. Chylomicrons and VLDL","C. LDL","D. IDL"]','B','Lipoprotein lipase hydrolyzes triacylglycerols in chylomicrons and VLDL in capillary beds, releasing free fatty acids for tissue uptake. LPL deficiency causes familial hyperchylomicronemia (Type I hyperlipidemia) with massive accumulation of chylomicrons and VLDL, presenting with eruptive xanthomas and pancreatitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Lipid Metabolism','medium','mcq','Which transport system is required to shuttle long-chain fatty acyl groups across the inner mitochondrial membrane for beta-oxidation?','["A. Malate-aspartate shuttle","B. Citrate shuttle","C. Carnitine shuttle (carnitine acyltransferase system)","D. Glycerol-3-phosphate shuttle"]','C','Long-chain fatty acids cannot cross the inner mitochondrial membrane directly. They are first converted to fatty acyl-CoA, then transferred to carnitine by carnitine palmitoyltransferase I (CPT-I) on the outer membrane, transported as acylcarnitine, and reconverted to acyl-CoA by CPT-II inside the mitochondria. Malonyl-CoA (from active lipogenesis) inhibits CPT-I, preventing simultaneous synthesis and oxidation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Lipid Metabolism','easy','mcq','Familial hypercholesterolaemia (FH) is caused by mutations in which receptor, resulting in elevated LDL-cholesterol?','["A. Insulin receptor","B. VLDL receptor","C. Scavenger receptor SR-B1","D. LDL receptor"]','D','Familial hypercholesterolaemia is caused by loss-of-function mutations in the LDL receptor (LDLR) gene. Without functional LDLR, LDL particles cannot be cleared from plasma, resulting in markedly elevated LDL-cholesterol, premature atherosclerosis, tendon xanthomas, and corneal arcus. Heterozygotes have LDL ~2x normal; homozygotes ~4-6x normal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Lipid Metabolism','hard','mcq','The NADPH required for fatty acid synthesis in the cytoplasm is primarily provided by which pathway?','["A. Pentose phosphate pathway","B. Oxidative phosphorylation","C. Beta-oxidation","D. TCA cycle"]','A','The pentose phosphate pathway (hexose monophosphate shunt) generates NADPH, which is the primary reducing equivalent required for fatty acid synthesis and cholesterol synthesis in the cytoplasm. NADPH is also critical for the regeneration of reduced glutathione and the function of cytochrome P450 enzymes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Lipid Metabolism','medium','mcq','Which of the following describes the role of apolipoprotein C-II (ApoC-II) in lipid metabolism?','["A. It is the ligand for the LDL receptor on hepatocytes","B. It activates lipoprotein lipase on capillary endothelium","C. It mediates reverse cholesterol transport via LCAT activation","D. It inhibits VLDL secretion from the liver"]','B','ApoC-II is a cofactor required to activate lipoprotein lipase (LPL) on capillary endothelial cells. ApoC-II is transferred from HDL to chylomicrons and VLDL in circulation. Deficiency of ApoC-II mimics LPL deficiency, causing hypertriglyceridemia. ApoB-100 is the LDL receptor ligand; ApoA-I activates LCAT.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Amino Acid & Protein Metabolism','easy','mcq','Which coenzyme is required by all aminotransferase (transaminase) enzymes for transamination reactions?','["A. Pyridoxal phosphate (PLP)","B. NAD+","C. Thiamine pyrophosphate","D. Cobalamin"]','A','Pyridoxal phosphate (PLP), the active form of vitamin B6, is the essential coenzyme for all aminotransferases. It forms a Schiff base with the amino group of the amino acid substrate. The amino group is transferred to alpha-ketoglutarate to form glutamate, which then donates its nitrogen in the urea cycle.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Amino Acid & Protein Metabolism','medium','mcq','In the urea cycle, which enzyme catalyzes the rate-limiting step and is found exclusively in the mitochondrial matrix?','["A. Argininosuccinate synthetase","B. Carbamoyl phosphate synthetase I","C. Arginase","D. Ornithine transcarbamylase"]','B','Carbamoyl phosphate synthetase I (CPS-I) catalyzes the first and rate-limiting step of the urea cycle, combining NH3, CO2, and 2 ATP to form carbamoyl phosphate. It is allosterically activated by N-acetylglutamate (NAG). CPS-I deficiency causes hyperammonemia without elevated urinary orotic acid.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Amino Acid & Protein Metabolism','medium','mcq','A newborn presents with a musty odour to urine, fair complexion, and intellectual disability if untreated. Plasma phenylalanine is markedly elevated. Which enzyme is deficient?','["A. Tyrosine hydroxylase","B. Homogentisate oxidase","C. Phenylalanine hydroxylase","D. Fumarylacetoacetate hydrolase"]','C','Phenylketonuria (PKU) is caused by deficiency of phenylalanine hydroxylase (PAH), which converts phenylalanine to tyrosine. Accumulation of phenylalanine and its transamination product phenylpyruvate causes intellectual disability and hypopigmentation (since tyrosine is needed for melanin). Treatment is a low-phenylalanine diet commenced within days of birth.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Amino Acid & Protein Metabolism','medium','mcq','Which of the following amino acids is the most important gluconeogenic amino acid transported from muscle to liver during fasting, participating in the glucose-alanine cycle?','["A. Arginine","B. Glutamine","C. Serine","D. Alanine"]','D','Alanine is the most important gluconeogenic amino acid in the glucose-alanine cycle. Muscle pyruvate is transaminated with glutamate to form alanine, which is released into blood, taken up by the liver, and converted back to pyruvate for gluconeogenesis. The amino group is released as urea. This cycle transfers nitrogen waste from muscle to liver without generating ammonia in blood.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Amino Acid & Protein Metabolism','hard','mcq','Which two amino acids are classified as purely ketogenic (cannot be converted to glucose)?','["A. Leucine and lysine","B. Phenylalanine and tyrosine","C. Isoleucine and threonine","D. Tryptophan and methionine"]','A','Leucine and lysine are the only two purely ketogenic amino acids; they are degraded to acetyl-CoA or acetoacetate only and cannot be converted to glucose. All other amino acids are either purely glucogenic or both glucogenic and ketogenic. This distinction is critical for understanding metabolic responses in diabetes and starvation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Amino Acid & Protein Metabolism','medium','mcq','Glutamate dehydrogenase in hepatocyte mitochondria catalyzes oxidative deamination of glutamate to produce free ammonia (NH3). It is allosterically inhibited by which molecule?','["A. ADP","B. GTP","C. NAD+","D. Alpha-ketoglutarate"]','B','Glutamate dehydrogenase (GDH) converts glutamate to alpha-ketoglutarate, releasing NH3. GDH is allosterically activated by ADP and inhibited by GTP (and NADH). This links urea cycle activity to cellular energy status: when GTP is high (energy replete), GDH is inhibited, reducing ammonia production and urea cycle flux. Leucine is also an allosteric activator of GDH.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Amino Acid & Protein Metabolism','medium','mcq','A patient with homocystinuria has elevated plasma homocysteine and reduced methionine. Homocysteine cannot be converted to cystathionine. Which enzyme and cofactor are most likely deficient?','["A. Methionine adenosyltransferase requiring ATP","B. Methylenetetrahydrofolate reductase requiring FAD","C. Cystathionine beta-synthase requiring pyridoxal phosphate","D. Methionine synthase requiring cobalamin"]','C','Cystathionine beta-synthase (CBS) condenses homocysteine with serine to form cystathionine, requiring PLP (vitamin B6) as cofactor. CBS deficiency is the most common cause of classic homocystinuria, presenting with lens dislocation (downward), Marfanoid habitus, intellectual disability, and thromboembolic events. High-dose pyridoxine is therapeutic in pyridoxine-responsive cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Amino Acid & Protein Metabolism','easy','mcq','In the urea cycle, one nitrogen atom in urea comes from free ammonia and the other comes from which amino acid, which serves as the nitrogen donor?','["A. Glutamine","B. Ornithine","C. Arginine","D. Aspartate"]','D','The two nitrogen atoms in urea have different origins: one comes from NH3 (via CPS-I forming carbamoyl phosphate), and the other comes from aspartate (which donates its amino group to form argininosuccinate via argininosuccinate synthetase). The carbon and oxygen of urea come from CO2 (bicarbonate). The net reaction consumes 4 high-energy phosphate bonds per urea molecule.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Amino Acid & Protein Metabolism','hard','mcq','Which of the following statements correctly describes protein secondary structure?','["A. It includes alpha-helices and beta-sheets stabilized by hydrogen bonds between backbone atoms","B. It is determined by disulfide bonds between cysteine residues","C. It refers to the three-dimensional folding of the entire polypeptide chain","D. It describes the spatial arrangement of multiple polypeptide subunits"]','A','Secondary structure refers to local, regular folding patterns of the polypeptide backbone, primarily alpha-helices and beta-pleated sheets, which are stabilized by hydrogen bonds between backbone carbonyl oxygen and amide hydrogen atoms. Tertiary structure refers to overall 3D folding; quaternary structure describes multi-subunit arrangements; disulfide bonds contribute to tertiary and quaternary structure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Amino Acid & Protein Metabolism','medium','mcq','A child presents with recurrent episodes of vomiting, ataxia, and a sweet maple syrup odour to urine after protein feeding. Plasma branched-chain amino acids are markedly elevated. Which enzyme complex is deficient?','["A. Phenylalanine hydroxylase","B. Branched-chain alpha-keto acid dehydrogenase (BCKDH)","C. Propionyl-CoA carboxylase","D. Glutaryl-CoA dehydrogenase"]','B','Maple syrup urine disease (MSUD) is caused by deficiency of the branched-chain alpha-keto acid dehydrogenase (BCKDH) complex, which decarboxylates the keto acids derived from leucine, isoleucine, and valine. Accumulation of these branched-chain keto acids produces the characteristic sweet odour and causes encephalopathy. Thiamine is a cofactor for BCKDH; some patients respond to thiamine supplementation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Enzyme Kinetics & Cofactors','easy','mcq','In Michaelis-Menten kinetics, the Km is defined as which of the following?','["A. The substrate concentration at which reaction velocity is half of Vmax","B. The maximum velocity of the enzyme","C. The equilibrium dissociation constant of the enzyme-substrate complex","D. The substrate concentration at which the enzyme is fully saturated"]','A','Km (Michaelis constant) is defined as the substrate concentration [S] at which the reaction velocity equals Vmax/2. It is a measure of the enzyme''s affinity for its substrate: a low Km indicates high affinity (enzyme reaches half-maximal velocity at low [S]), while a high Km indicates low affinity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Enzyme Kinetics & Cofactors','medium','mcq','A drug competes with the natural substrate for the active site of an enzyme. On a Lineweaver-Burk (double-reciprocal) plot, which pattern would be observed?','["A. Increased Vmax and unchanged Km","B. Unchanged Vmax and increased apparent Km","C. Decreased Vmax and unchanged Km","D. Decreased Vmax and decreased Km"]','B','Competitive inhibitors compete with substrate for the active site, which can be overcome by adding more substrate. Therefore, Vmax is unchanged (maximum activity is still achievable), but apparent Km is increased (more substrate is needed to reach half-maximal velocity). On a Lineweaver-Burk plot, lines converge on the y-axis (same y-intercept, different x-intercept).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Enzyme Kinetics & Cofactors','medium','mcq','Which of the following is a characteristic of an uncompetitive inhibitor?','["A. It binds to the free enzyme only and increases apparent Km","B. It binds to an allosteric site, reducing enzyme activity without changing Km","C. It binds to the enzyme-substrate complex and decreases both Vmax and apparent Km","D. It forms an irreversible covalent bond with the active site"]','C','Uncompetitive inhibitors bind only to the enzyme-substrate (ES) complex, stabilizing it and preventing product formation. This decreases both Vmax and apparent Km proportionally. On a Lineweaver-Burk plot, parallel lines are observed (both slope intercepts shift). This differs from non-competitive inhibition where Km is unchanged and only Vmax decreases.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Enzyme Kinetics & Cofactors','medium','mcq','Which vitamin serves as the precursor to NAD+ and NADP+, essential cofactors for numerous oxidation-reduction reactions?','["A. Vitamin B1 (Thiamine)","B. Vitamin B2 (Riboflavin)","C. Vitamin B5 (Pantothenic acid)","D. Vitamin B3 (Niacin)"]','D','Niacin (nicotinic acid or nicotinamide, vitamin B3) is the precursor for NAD+ and NADP+. These cofactors accept electrons (as hydride ions) in oxidative metabolism. Tryptophan can also be converted to NAD+ (60:1 ratio). Niacin deficiency causes pellagra (4 Ds: diarrhea, dermatitis, dementia, death).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Enzyme Kinetics & Cofactors','hard','mcq','Aspirin irreversibly inhibits cyclooxygenase (COX) by acetylating a serine residue in the active site. This is an example of which type of enzyme inhibition?','["A. Irreversible inhibition","B. Non-competitive inhibition","C. Uncompetitive inhibition","D. Competitive inhibition"]','A','Aspirin covalently modifies cyclooxygenase by acetylating Ser530 in the active site channel, permanently blocking access to arachidonic acid. This irreversible inhibition persists for the life of the platelet (about 10 days) since platelets cannot synthesize new protein, accounting for aspirin''s prolonged antiplatelet effect.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Enzyme Kinetics & Cofactors','medium','mcq','Thiamine pyrophosphate (TPP) is a coenzyme required by which set of enzymes?','["A. Pyruvate carboxylase, acetyl-CoA carboxylase, and propionyl-CoA carboxylase","B. Pyruvate dehydrogenase, alpha-ketoglutarate dehydrogenase, and transketolase","C. Aminotransferases, decarboxylases, and glycogen phosphorylase","D. Lactate dehydrogenase, malate dehydrogenase, and isocitrate dehydrogenase"]','B','Thiamine pyrophosphate (TPP) is required by: (1) pyruvate dehydrogenase complex (PDH), (2) alpha-ketoglutarate dehydrogenase complex in the TCA cycle, (3) branched-chain keto acid dehydrogenase (BCKDH), and (4) transketolase in the pentose phosphate pathway. Thiamine deficiency impairs all these enzymes, causing beriberi and Wernicke-Korsakoff syndrome.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Enzyme Kinetics & Cofactors','medium','mcq','An allosteric enzyme shows sigmoidal kinetics rather than hyperbolic kinetics. Which of the following best explains this phenomenon?','["A. The enzyme has a single active site with low substrate affinity","B. The enzyme is subject to competitive inhibition by its product","C. The enzyme undergoes cooperative binding where binding of one substrate molecule increases affinity for subsequent molecules","D. The enzyme requires covalent modification for activation"]','C','Allosteric enzymes typically show sigmoidal velocity curves due to cooperative substrate binding. When one substrate molecule binds, it induces a conformational change (T-state to R-state) that increases affinity at other subunits. This is analogous to oxygen binding to hemoglobin and allows sensitive regulation around a threshold substrate concentration.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Enzyme Kinetics & Cofactors','easy','mcq','Coenzyme A (CoA) is derived from which vitamin and is essential for acyl group transfer reactions in metabolism?','["A. Vitamin B2 (Riboflavin)","B. Vitamin B12 (Cobalamin)","C. Vitamin B6 (Pyridoxine)","D. Vitamin B5 (Pantothenic acid)"]','D','Coenzyme A is synthesized from pantothenic acid (vitamin B5), ATP, cysteine, and other components. CoA carries acyl groups via its thiol group and is essential for fatty acid synthesis and oxidation, the TCA cycle (acetyl-CoA, succinyl-CoA), and the pyruvate dehydrogenase reaction. Pantothenic acid deficiency is rare but causes the burning feet syndrome.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Enzyme Kinetics & Cofactors','hard','mcq','On a Lineweaver-Burk plot, the y-intercept represents which kinetic parameter?','["A. 1/Vmax","B. Vmax","C. Km","D. -1/Km"]','A','In a Lineweaver-Burk (double-reciprocal) plot, 1/V is plotted against 1/[S]. The y-intercept equals 1/Vmax, the x-intercept equals -1/Km, and the slope equals Km/Vmax. This linear transformation allows Km and Vmax to be determined graphically from enzyme kinetic data even when saturation is not achieved experimentally.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Enzyme Kinetics & Cofactors','medium','mcq','FAD and FMN are coenzymes derived from riboflavin (vitamin B2) and function in which of the following capacities in metabolism?','["A. They carry acetyl groups in the TCA cycle","B. They serve as electron carriers in oxidation-reduction reactions, accepting 2 electrons and 2 protons to form FADH2 or FMNH2","C. They donate phosphate groups in substrate-level phosphorylation","D. They act as methyl group donors in one-carbon metabolism"]','B','FAD (flavin adenine dinucleotide) and FMN (flavin mononucleotide), derived from riboflavin, function as prosthetic groups or coenzymes in oxidoreductases. They accept 2 electrons and 2 protons to form FADH2 or FMNH2. Key enzymes include succinate dehydrogenase (Complex II), fatty acyl-CoA dehydrogenase in beta-oxidation, and the dihydrolipoyl dehydrogenase (E3) subunit of PDH and BCKDH.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Vitamins & Minerals','easy','mcq','A patient presents with night blindness, Bitot''s spots, and xerophthalmia. Which vitamin deficiency is most likely?','["A. Vitamin A (retinol)","B. Vitamin D","C. Vitamin K","D. Vitamin E"]','A','Vitamin A (retinol) deficiency causes night blindness (impaired rod function due to reduced rhodopsin synthesis), Bitot''s spots (foamy white plaques on conjunctiva), xerophthalmia (dry eye), and corneal ulceration. Vitamin A is a fat-soluble vitamin required for vision, epithelial integrity, and immune function.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Vitamins & Minerals','medium','mcq','A patient presents with perifollicular petechiae, swollen bleeding gums, poor wound healing, and corkscrew hairs. Which vitamin deficiency explains these findings?','["A. Vitamin D","B. Vitamin C (ascorbic acid)","C. Vitamin B12","D. Vitamin K"]','B','Scurvy results from vitamin C (ascorbic acid) deficiency. Vitamin C is essential for hydroxylation of proline and lysine in collagen synthesis, catalyzed by prolyl and lysyl hydroxylases (requiring Fe2+). Defective collagen causes perifollicular hemorrhage, poor wound healing, swollen bleeding gums, and corkscrew hairs. It is also required for iron absorption and is an antioxidant.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Vitamins & Minerals','medium','mcq','Which fat-soluble vitamin acts as an antioxidant protecting polyunsaturated fatty acids in cell membranes from lipid peroxidation?','["A. Vitamin A","B. Vitamin D","C. Vitamin E (tocopherol)","D. Vitamin K"]','C','Vitamin E (alpha-tocopherol) is the principal lipid-soluble antioxidant in cell membranes, protecting polyunsaturated fatty acids from free radical chain reactions (lipid peroxidation). Deficiency causes hemolytic anemia in premature infants, spinocerebellar degeneration, and peripheral neuropathy. Vitamin E is regenerated by vitamin C in the cytosol.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Vitamins & Minerals','medium','mcq','Vitamin K is required as a cofactor for the gamma-carboxylation of glutamate residues in which clotting factors?','["A. Factors I, II, III, and IV","B. Von Willebrand factor and fibrinogen","C. Factors V, VIII, XI, and XII","D. Factors II, VII, IX, and X (and proteins C, S, Z)"]','D','Vitamin K is essential for the gamma-carboxylation of glutamate residues in factors II (prothrombin), VII, IX, and X, as well as anticoagulant proteins C, S, and Z. This carboxylation allows these proteins to bind calcium and phospholipid surfaces. Warfarin inhibits vitamin K epoxide reductase (VKOR), blocking recycling of active vitamin K and prolonging the INR.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Vitamins & Minerals','hard','mcq','A strict vegan presents with megaloblastic anemia, peripheral neuropathy, and subacute combined degeneration of the spinal cord. Serum cobalamin is low. Which biochemical reaction is most directly impaired?','["A. Conversion of methylmalonyl-CoA to succinyl-CoA and remethylation of homocysteine to methionine","B. Reduction of ribonucleotides to deoxyribonucleotides","C. Hydroxylation of proline and lysine in collagen","D. Conversion of tryptophan to niacin"]','A','Vitamin B12 (cobalamin) is required for two reactions: (1) conversion of methylmalonyl-CoA to succinyl-CoA (by mutase, requiring adenosylcobalamin), and (2) remethylation of homocysteine to methionine (by methionine synthase, requiring methylcobalamin). Deficiency causes methylmalonic aciduria, hyperhomocysteinemia, megaloblastic anemia, and subacute combined degeneration (posterior and lateral spinal cord columns).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Vitamins & Minerals','medium','mcq','Folate deficiency causes megaloblastic anemia primarily because it impairs synthesis of which nucleotide?','["A. Purines only","B. dTMP (thymidylate), thereby blocking DNA synthesis","C. Pyrimidines only","D. ATP, thereby reducing energy for erythropoiesis"]','B','Folate (as 5,10-methyleneTHF) provides the methyl group for thymidylate synthase to convert dUMP to dTMP (thymidylate). Without dTMP, DNA synthesis is severely impaired. Cells continue to grow but cannot divide effectively, resulting in the large hypersegmented neutrophils and large red cell precursors (macrocytes) characteristic of megaloblastic anemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Vitamins & Minerals','medium','mcq','Which of the following fat-soluble vitamins is toxic in excess, and chronic overconsumption causes hepatotoxicity, pseudotumor cerebri, and teratogenicity?','["A. Vitamin E","B. Vitamin K","C. Vitamin A","D. Vitamin C"]','C','Vitamin A (retinol) is the most toxic fat-soluble vitamin in excess. Chronic hypervitaminosis A causes hepatotoxicity, pseudotumor cerebri (raised intracranial pressure), dry skin, alopecia, and bone pain. Teratogenicity (causing neural tube defects and craniofacial abnormalities) is a serious concern in pregnancy. Isotretinoin (a vitamin A analog) is highly teratogenic; vitamins E and K have low toxicity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Vitamins & Minerals','easy','mcq','Zinc is an essential cofactor for which important antioxidant enzyme, and which clinical condition is characteristic of severe inherited zinc deficiency?','["A. Glutathione peroxidase; Menkes disease","B. Thioredoxin reductase; Hartnup disease","C. Catalase; Wilson disease","D. Cu/Zn superoxide dismutase; acrodermatitis enteropathica"]','D','Zinc is a cofactor for Cu/Zn superoxide dismutase (SOD1), alkaline phosphatase, carbonic anhydrase, DNA polymerase, and over 300 other enzymes. Acrodermatitis enteropathica is a rare autosomal-recessive disorder of zinc absorption (SLC39A4 mutation) causing periorificial and acral dermatitis, alopecia, diarrhea, and impaired immunity. Dietary zinc supplementation is curative.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Vitamins & Minerals','hard','mcq','Which vitamin deficiency is associated with dermatitis, diarrhea, dementia, and in severe cases death (the "4 Ds")?','["A. Vitamin B3 (Niacin)","B. Vitamin B2 (Riboflavin)","C. Vitamin B1 (Thiamine)","D. Vitamin B6 (Pyridoxine)"]','A','Pellagra is caused by niacin (vitamin B3) deficiency or tryptophan deficiency (since tryptophan can be converted to niacin). It presents with the 4 Ds: Dermatitis (photosensitive, Casal''s necklace), Diarrhea, Dementia, and Death. It occurs in populations subsisting on corn (maize) without lime processing, or with carcinoid syndrome (tryptophan diverted to serotonin synthesis).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Vitamins & Minerals','medium','mcq','Rickets in children and osteomalacia in adults are caused by deficiency of which vitamin, which is required for calcium and phosphate absorption from the gut?','["A. Vitamin A","B. Vitamin D","C. Vitamin C","D. Vitamin E"]','B','Vitamin D (cholecalciferol) is hydroxylated in the liver to 25-hydroxyvitamin D, then in the kidney to the active form 1,25-dihydroxyvitamin D (calcitriol). Calcitriol stimulates intestinal absorption of calcium and phosphate by inducing synthesis of calcium-binding proteins. Deficiency causes rickets (children) with bowing of legs, and osteomalacia (adults) with bone pain and proximal myopathy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - DNA','easy','mcq','In the Watson-Crick model of DNA, which of the following base pairing rules is correct?','["A. Guanine pairs with cytosine via three hydrogen bonds","B. Adenine pairs with cytosine via two hydrogen bonds","C. Adenine pairs with uracil in double-stranded DNA","D. Guanine pairs with thymine via two hydrogen bonds"]','A','In DNA, base pairing follows Chargaff''s rules: A pairs with T via 2 hydrogen bonds, and G pairs with C via 3 hydrogen bonds. The higher the G-C content in a DNA molecule, the higher its melting temperature (Tm) because more energy is required to break the stronger triple hydrogen bonds. Uracil replaces thymine in RNA but not in DNA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - DNA','medium','mcq','Which enzyme relieves torsional stress ahead of the replication fork by introducing transient breaks in the DNA backbone?','["A. DNA polymerase III","B. Topoisomerase","C. Primase","D. DNA helicase"]','B','Topoisomerases relieve torsional stress (supercoiling) generated during DNA replication and transcription. Type I topoisomerases create transient single-strand breaks; Type II topoisomerases (including DNA gyrase in bacteria) create transient double-strand breaks. Fluoroquinolone antibiotics target bacterial DNA gyrase, and camptothecin targets eukaryotic topoisomerase I.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - DNA','medium','mcq','DNA replication is described as semiconservative. What does this mean?','["A. Each new DNA molecule contains two entirely new strands","B. Half of all DNA molecules are entirely original and half are entirely new","C. Each new DNA molecule contains one original strand and one newly synthesized strand","D. Each new DNA molecule contains alternating original and new nucleotides"]','C','Semiconservative replication, demonstrated by the Meselson-Stahl experiment using density labelling with 15N, means that each daughter DNA molecule retains one parental (template) strand and one newly synthesized complementary strand. This ensures faithful transmission of genetic information and provides one intact template strand for error correction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - DNA','medium','mcq','A patient with xeroderma pigmentosum (XP) has extreme UV sensitivity and high risk of skin cancer. Which DNA repair mechanism is defective in XP?','["A. Base excision repair","B. Mismatch repair","C. Non-homologous end joining","D. Nucleotide excision repair"]','D','Xeroderma pigmentosum results from defects in nucleotide excision repair (NER), the pathway that removes bulky, helix-distorting lesions such as UV-induced thymine dimers (cyclobutane pyrimidine dimers). Without NER, these lesions cause C-to-T transitions and CC-to-TT tandem mutations during replication, leading to early-onset skin cancers including melanoma and squamous cell carcinoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - DNA','hard','mcq','Which enzyme synthesizes a short RNA primer that provides the 3''-OH group needed to initiate DNA synthesis at replication origins?','["A. Primase (RNA primase)","B. DNA polymerase III","C. DNA polymerase I","D. Telomerase"]','A','Primase (a specialized RNA polymerase) synthesizes short RNA primers (5-10 nucleotides) complementary to the DNA template strand. These primers provide the essential free 3''-OH group that DNA polymerase requires to add new nucleotides. RNA primers are later removed by DNA polymerase I (5'' to 3'' exonuclease activity in prokaryotes) and replaced with DNA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - DNA','medium','mcq','Hereditary nonpolyposis colorectal cancer (Lynch syndrome) is caused by mutations in genes encoding which DNA repair proteins?','["A. BRCA1 and BRCA2","B. MLH1, MSH2, and other mismatch repair proteins","C. XPA, XPB, and other nucleotide excision repair proteins","D. ATM and CHEK2 kinases"]','B','Lynch syndrome (HNPCC) is caused by germline mutations in mismatch repair (MMR) genes, most commonly MLH1 and MSH2, followed by MSH6 and PMS2. MMR corrects base mismatches and small insertion-deletion loops arising from replication errors. Defective MMR leads to microsatellite instability (MSI), a hallmark of Lynch syndrome tumors of the colon, endometrium, and other sites.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - DNA','medium','mcq','A mutation that changes a single base pair, converting an amino acid codon into a stop codon, is classified as which type of mutation?','["A. Missense mutation","B. Silent mutation","C. Nonsense mutation","D. Frameshift mutation"]','C','A nonsense mutation converts an amino acid codon to a stop codon (UAA, UAG, or UGA) via a single base substitution, resulting in premature termination of translation and a truncated, usually nonfunctional protein. Many severe genetic diseases including Duchenne muscular dystrophy and some forms of beta-thalassaemia result from nonsense mutations. Missense mutations change one amino acid to another.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - DNA','easy','mcq','Which of the following correctly describes the difference between the leading strand and the lagging strand during DNA replication?','["A. The leading strand is synthesized in the 3'' to 5'' direction; the lagging strand is synthesized 5'' to 3''","B. The leading strand is synthesized by DNA polymerase I; the lagging strand by DNA polymerase III","C. The leading strand requires a primer; the lagging strand does not","D. The leading strand is synthesized continuously 5'' to 3''; the lagging strand is synthesized discontinuously as Okazaki fragments in the same 5'' to 3'' direction"]','D','DNA polymerase can only synthesize DNA in the 5'' to 3'' direction. On the leading strand (template runs 3'' to 5''), synthesis is continuous in the direction of fork movement. On the lagging strand (template runs 5'' to 3''), synthesis proceeds away from the fork in short discontinuous Okazaki fragments (100-200 nt in eukaryotes), each requiring its own RNA primer.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - DNA','hard','mcq','Telomerase maintains telomere length in germ cells and cancer cells. Which enzymatic activity does telomerase possess?','["A. It is an RNA-dependent DNA polymerase (reverse transcriptase) that uses its own RNA component as a template","B. It is a DNA-dependent DNA polymerase","C. It is an endonuclease that removes damaged terminal sequences","D. It is a helicase that unwinds telomeric G-quadruplex structures"]','A','Telomerase is a ribonucleoprotein reverse transcriptase that uses its internal RNA component (hTERC) as a template to add repetitive TTAGGG sequences to the 3'' ends of chromosomes. It compensates for the end-replication problem. Telomerase is active in stem cells, germ cells, and greater than 85% of cancers, making it an anticancer target.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - DNA','medium','mcq','In base excision repair (BER), which enzyme is responsible for recognizing and removing a damaged base by cleaving the N-glycosidic bond, creating an AP site?','["A. AP endonuclease","B. DNA glycosylase","C. DNA polymerase beta","D. XRCC1-ligase III complex"]','B','DNA glycosylases initiate base excision repair by recognizing and cleaving the N-glycosidic bond between the damaged base and deoxyribose, creating an AP (apurinic/apyrimidinic) site. AP endonuclease then cuts the sugar-phosphate backbone, followed by DNA polymerase beta filling the gap and ligase sealing the nick. Different glycosylases have specificity for particular types of base damage (e.g., uracil-DNA glycosylase removes uracil from DNA).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - Gene Expression','easy','mcq','Which RNA polymerase is responsible for transcribing protein-coding genes (mRNA) in eukaryotes?','["A. RNA polymerase II","B. RNA polymerase I","C. RNA polymerase III","D. Reverse transcriptase"]','A','In eukaryotes, RNA polymerase II transcribes protein-coding genes into pre-mRNA. RNA pol I transcribes ribosomal RNA (rRNA), and RNA pol III transcribes tRNA and small RNAs including 5S rRNA. Alpha-amanitin (from Amanita phalloides, the death cap mushroom) specifically inhibits RNA pol II, causing fulminant hepatic failure by blocking mRNA synthesis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - Gene Expression','medium','mcq','Which post-transcriptional modification protects the 5'' end of eukaryotic mRNA from exonucleolytic degradation and is required for ribosome binding?','["A. Polyadenylation (poly-A tail)","B. 5'' 7-methylguanosine (m7G) cap","C. Removal of introns by splicing","D. AAUAAA polyadenylation signal recognition"]','B','The 5'' 7-methylguanosine (m7G) cap is added co-transcriptionally in a 5''-to-5'' triphosphate linkage to the first nucleotide of the pre-mRNA. It protects mRNA from 5'' exonuclease degradation, facilitates nuclear export, and is recognized by eIF4E during cap-dependent translation initiation. The poly-A tail protects the 3'' end.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - Gene Expression','medium','mcq','The genetic code is said to be degenerate (redundant). What does this mean?','["A. Most codons encode more than one amino acid","B. Some amino acids have no codon","C. Multiple codons can encode the same amino acid","D. Stop codons can also encode amino acids in some contexts"]','C','The genetic code is degenerate because most of the 20 amino acids are encoded by more than one codon (synonymous codons). For example, leucine is encoded by 6 codons and serine by 6 codons. Degeneracy is predominantly in the third (wobble) position of the codon. This provides protection against missense mutations since many base changes at the third position still encode the same amino acid.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - Gene Expression','medium','mcq','Translation begins at the AUG start codon. Which amino acid does AUG encode, and what is the corresponding initiator tRNA called?','["A. Valine; initiator Val-tRNA","B. Leucine; initiator Leu-tRNA","C. Formylmethionine; used in both prokaryotes and eukaryotes","D. Methionine; initiator Met-tRNA (tRNA-Met(i))"]','D','AUG encodes methionine (Met) in both prokaryotes and eukaryotes. In prokaryotes, the initiator amino acid is formylmethionine (fMet), carried by tRNA-fMet. In eukaryotes, it is methionine (Met) carried by the initiator tRNA-Met(i). The initiator tRNA enters the P site of the ribosome directly, unlike elongator tRNAs which enter the A site first.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - Gene Expression','hard','mcq','Rifampin (rifampicin) inhibits bacterial RNA polymerase. Which step of transcription does it specifically block?','["A. Initiation by binding to the beta subunit and blocking the RNA exit tunnel once 2-3 nucleotides are formed","B. Elongation by blocking the RNA exit channel","C. Termination by preventing Rho factor binding","D. Post-transcriptional capping of bacterial mRNA"]','A','Rifampin binds to the beta subunit of bacterial RNA polymerase and blocks the RNA exit tunnel, inhibiting transcription initiation once the first 2-3 nucleotides have been incorporated. It does not inhibit eukaryotic RNA polymerases. Rifampin is a key drug for tuberculosis and meningococcal prophylaxis. Resistance arises from mutations in the rpoB gene encoding the beta subunit.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - Gene Expression','medium','mcq','Which post-translational modification targets proteins for proteasomal degradation by the ubiquitin-proteasome system?','["A. Phosphorylation by protein kinase A","B. Polyubiquitination via Lys48-linked ubiquitin chains","C. N-linked glycosylation in the endoplasmic reticulum","D. Hydroxylation of proline residues"]','B','The ubiquitin-proteasome system (UPS) degrades misfolded, damaged, or regulatory proteins. Ubiquitin is activated (E1), conjugated to E2, and ligated to target protein lysine residues by E3 ligases. Polyubiquitin chains linked via Lys48 serve as the canonical degradation signal recognized by the 26S proteasome. The UPS regulates cell cycle (cyclin degradation), NF-kB activation, and p53 stability.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - Gene Expression','medium','mcq','In eukaryotic pre-mRNA splicing, which RNA-protein complexes recognize splice site sequences and catalyze intron removal?','["A. Ribosomes","B. Exosomes","C. Spliceosomes (comprised of snRNPs: U1, U2, U4, U5, U6)","D. Signal recognition particles (SRPs)"]','C','Pre-mRNA splicing is carried out by the spliceosome, a large ribonucleoprotein complex containing five small nuclear ribonucleoprotein particles (snRNPs): U1, U2, U4, U5, and U6, plus additional splicing factors. The snRNAs recognize the 5'' splice site, branch point adenosine, and 3'' splice site. Splicing occurs via two transesterification reactions, releasing the intron as a lariat structure and ligating the exons.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - Gene Expression','easy','mcq','Aminoglycosides (e.g., gentamicin) and tetracyclines inhibit bacterial translation. What are their respective mechanisms?','["A. Aminoglycosides block peptide bond formation; tetracyclines inhibit ribosome assembly","B. Both inhibit the peptidyl transferase activity of the 50S subunit","C. Aminoglycosides inhibit initiation; tetracyclines block elongation factor EF-G","D. Aminoglycosides cause misreading of mRNA at the 30S subunit; tetracyclines block aminoacyl-tRNA entry to the A site of the 30S subunit"]','D','Aminoglycosides bind the 16S rRNA of the 30S ribosomal subunit, causing misreading of the genetic code and incorporation of incorrect amino acids. Tetracyclines also bind the 30S subunit and block aminoacyl-tRNA from entering the A site, preventing elongation. Both target the bacterial ribosome without affecting the eukaryotic 80S ribosome (at therapeutic concentrations).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - Gene Expression','hard','mcq','N-linked glycosylation of proteins begins in which subcellular compartment and involves transfer of an oligosaccharide from dolichol phosphate to asparagine residues?','["A. Rough endoplasmic reticulum (RER)","B. Nucleus","C. Golgi apparatus","D. Cytoplasm"]','A','N-linked glycosylation begins in the rough endoplasmic reticulum (RER), where a preformed 14-sugar oligosaccharide (Glc3Man9GlcNAc2) is transferred en bloc from dolichol phosphate to asparagine residues in Asn-X-Ser/Thr sequons by oligosaccharyltransferase. Further processing and trimming occurs in the RER and Golgi. This modification is important for protein folding quality control, stability, and cell-surface receptor function.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - Gene Expression','medium','mcq','The lac operon in E. coli is a model for gene regulation. When lactose is absent and glucose is present, which state accurately describes operon regulation?','["A. Active: CAP protein binds and repressor is removed","B. Inactive: lac repressor is bound to operator and cAMP-CAP is not bound to promoter","C. Active: repressor is inactivated by allolactose","D. Inactive: repressor is bound and antitermination prevents elongation"]','B','When glucose is present (low cAMP) and lactose is absent (lac repressor protein bound to operator DNA), the lac operon is fully repressed. cAMP is required for CAP (catabolite activator protein) binding to the promoter to enhance RNA polymerase binding. Only when lactose is present (allolactose inactivates repressor) AND glucose is absent (high cAMP activates CAP) is the operon maximally expressed.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Energy Metabolism & Oxidative Phosphorylation','easy','mcq','Which complex of the electron transport chain is inhibited by cyanide and azide, blocking electron transfer to molecular oxygen?','["A. Complex IV (cytochrome c oxidase)","B. Complex II (succinate dehydrogenase)","C. Complex III (cytochrome bc1)","D. Complex I (NADH dehydrogenase)"]','A','Cyanide (CN-) and azide (N3-) inhibit Complex IV (cytochrome c oxidase), the final electron acceptor in the ETC, by binding to the heme iron of cytochrome a3 and preventing reduction of O2 to H2O. This blocks the entire ETC and ATP synthesis. Clinically, cyanide poisoning causes lactic acidosis, headache, and the characteristic bitter almond odour. Treatment includes hydroxocobalamin or sodium thiosulfate.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Energy Metabolism & Oxidative Phosphorylation','medium','mcq','2,4-Dinitrophenol (DNP) was historically used as a weight-loss agent. As a protonophore, what is its mechanism of action on oxidative phosphorylation?','["A. It inhibits ATP synthase, blocking ATP production","B. It dissipates the proton gradient across the inner mitochondrial membrane, uncoupling electron transport from ATP synthesis","C. It inhibits Complex I, reducing NADH oxidation","D. It inhibits the adenine nucleotide translocase, trapping ATP inside mitochondria"]','B','DNP and other uncouplers (protonophores) carry protons across the inner mitochondrial membrane down their concentration gradient, bypassing ATP synthase. This dissipates the proton-motive force as heat. Electron transport continues unchecked (consuming O2 and fuel), resulting in hyperthermia, diaphoresis, and potentially fatal hyperthermia. DNP was withdrawn from commercial use after multiple deaths in the 1930s.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Energy Metabolism & Oxidative Phosphorylation','medium','mcq','In brown adipose tissue (BAT), heat generation (thermogenesis) is mediated by which protein?','["A. UCP3","B. UCP2","C. UCP1 (thermogenin)","D. ATP synthase subunit c (F0)"]','C','UCP1 (thermogenin) in the inner mitochondrial membrane of brown adipocytes allows proton leak across the membrane, uncoupling electron transport from ATP synthesis and generating heat instead. BAT thermogenesis is activated by noradrenaline and is important in neonates and cold-adapted animals for non-shivering thermogenesis. BAT thermogenesis has attracted interest as an obesity treatment target.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Energy Metabolism & Oxidative Phosphorylation','medium','mcq','The chemiosmotic theory proposes that ATP synthesis is driven by which of the following?','["A. Direct substrate-level phosphorylation by ETC complexes","B. The NADH/NAD+ ratio in the mitochondrial matrix","C. The binding of ADP and Pi directly to cytochrome complexes","D. The electrochemical proton gradient (proton-motive force) across the inner mitochondrial membrane"]','D','Peter Mitchell''s chemiosmotic theory (Nobel Prize 1978) proposes that the electron transport chain pumps protons from the mitochondrial matrix to the intermembrane space, creating an electrochemical proton gradient (proton-motive force = electrical membrane potential + chemical pH gradient). This gradient drives protons back through ATP synthase (Complex V/F1F0-ATPase), powering ATP synthesis from ADP + Pi by rotary catalysis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Energy Metabolism & Oxidative Phosphorylation','hard','mcq','Rotenone (a pesticide) and amobarbital (amytal) specifically inhibit electron transport at which complex?','["A. Complex I (NADH: ubiquinone oxidoreductase)","B. Complex II (succinate dehydrogenase)","C. Complex III (cytochrome bc1 complex)","D. Complex IV (cytochrome c oxidase)"]','A','Rotenone and amobarbital (amytal) specifically inhibit Complex I by blocking electron transfer from the iron-sulfur clusters to ubiquinone. This prevents reoxidation of NADH by the ETC, inhibiting the TCA cycle and fatty acid oxidation. Rotenone is used as a pesticide and insecticide; its ability to induce parkinsonism in animal models has implicated Complex I inhibition in Parkinson''s disease pathogenesis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Energy Metabolism & Oxidative Phosphorylation','medium','mcq','NADH produced in the cytoplasm during glycolysis must be shuttled into the mitochondria. The malate-aspartate shuttle yields approximately how many ATP equivalents per cytoplasmic NADH compared to the glycerol-3-phosphate shuttle?','["A. Both yield 2.5 ATP per NADH","B. Malate-aspartate shuttle: ~2.5 ATP; glycerol-3-phosphate shuttle: ~1.5 ATP","C. Malate-aspartate shuttle: ~1.5 ATP; glycerol-3-phosphate shuttle: ~2.5 ATP","D. Both yield 1.5 ATP per NADH"]','B','The malate-aspartate shuttle transfers cytoplasmic NADH equivalents into the mitochondrial matrix as NADH, which enters Complex I and yields approximately 2.5 ATP. The glycerol-3-phosphate shuttle transfers electrons to FAD, forming FADH2 which enters at Complex II/ubiquinone, yielding only approximately 1.5 ATP per cytoplasmic NADH. Heart and liver primarily use the malate-aspartate shuttle; skeletal muscle uses the glycerol-3-phosphate shuttle.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Energy Metabolism & Oxidative Phosphorylation','medium','mcq','Reactive oxygen species (ROS) such as superoxide (O2 radical anion) are primarily generated at which sites in the ETC under conditions of high membrane potential?','["A. Complex II and Complex IV","B. ATP synthase (Complex V)","C. Complex I and Complex III (particularly at the ubisemiquinone radical)","D. Cytochrome c in the intermembrane space"]','C','The primary sites of superoxide generation in the ETC are Complex I (at the flavin mononucleotide/FMN site) and Complex III (at the ubisemiquinone site). When electron transport rate is slowed by high membrane potential or substrate overload, electrons leak to O2 forming superoxide. Cu/Zn-SOD and Mn-SOD convert superoxide to H2O2, which is further detoxified by catalase and glutathione peroxidase.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Energy Metabolism & Oxidative Phosphorylation','easy','mcq','Oligomycin inhibits ATP synthesis in isolated mitochondria. What would be the immediate effect on the proton-motive force and oxygen consumption?','["A. Proton-motive force decreases; oxygen consumption increases","B. Both proton-motive force and oxygen consumption decrease","C. Both proton-motive force and oxygen consumption increase","D. Proton-motive force increases; oxygen consumption decreases"]','D','Oligomycin blocks the F0 proton channel of ATP synthase, preventing proton re-entry into the matrix. With ATP synthase blocked, the proton gradient builds up (proton-motive force increases) because protons cannot return through their only available channel. This increased back-pressure on the ETC slows electron transport and oxygen consumption. This represents state 4 (controlled) respiration.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Energy Metabolism & Oxidative Phosphorylation','hard','mcq','Mitochondrial diseases caused by mutations in mtDNA show maternal inheritance. Which tissues are most severely affected?','["A. Brain, heart, and skeletal muscle, because they have the highest energy demands and are most dependent on oxidative phosphorylation","B. Bone and cartilage, because they have the highest mtDNA copy number","C. Liver and kidney, because they are the primary sites of mtDNA replication","D. Adipose tissue and skin, because they express the most mitochondrial proteins"]','A','Mitochondrial DNA encodes 13 subunits of the ETC and ATP synthase plus 22 tRNAs and 2 rRNAs. Tissues with the highest oxidative energy demands -- especially brain, heart, and skeletal muscle -- are most severely affected by mtDNA mutations. Classic mitochondrial diseases include MELAS (mitochondrial encephalomyopathy, lactic acidosis, stroke-like episodes), MERRF (myoclonic epilepsy with ragged red fibers), and Leber''s hereditary optic neuropathy (LHON).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Energy Metabolism & Oxidative Phosphorylation','medium','mcq','Antimycin A inhibits Complex III by blocking the Qi site. Which electron carriers would be expected to accumulate upstream of this block?','["A. Cytochrome c (oxidised form) and molecular O2","B. Reduced ubiquinol (QH2) and reduced cytochrome b","C. Oxidised NAD+ and FAD","D. FADH2 at Complex II and reduced ferredoxin"]','B','When Complex III is inhibited by antimycin A, electrons cannot flow from ubiquinol (QH2) to cytochrome c. Ubiquinol and reduced cytochrome b accumulate upstream of the block, while cytochrome c (downstream) becomes progressively oxidized and then unavailable for reduction. This halts the entire ETC, stops ATP production, and significantly increases superoxide generation from accumulated ubisemiquinone.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Metabolic Integration & Hormonal Control','easy','mcq','In the fed (postprandial) state, elevated insulin promotes which of the following metabolic processes?','["A. Glycogen synthesis, lipogenesis, and protein synthesis","B. Lipolysis and ketogenesis","C. Gluconeogenesis and glycogenolysis","D. Fatty acid oxidation and amino acid catabolism"]','A','Insulin is the key anabolic hormone of the fed state. It promotes glucose uptake (via GLUT-4 in muscle and adipose tissue), glycogen synthesis (activating glycogen synthase), lipogenesis (activating acetyl-CoA carboxylase), and protein synthesis. It simultaneously inhibits gluconeogenesis, glycogenolysis, lipolysis, and ketogenesis by inactivating their key regulatory enzymes via protein phosphatase 2B activation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Metabolic Integration & Hormonal Control','medium','mcq','Glucagon acts on the liver primarily through which intracellular signalling pathway to stimulate glycogenolysis and gluconeogenesis?','["A. Receptor tyrosine kinase leading to PI3K-Akt activation","B. G protein-coupled receptor leading to adenylyl cyclase-cAMP-PKA cascade","C. JAK-STAT pathway","D. IP3 and DAG leading to PKC and calmodulin kinase"]','B','Glucagon binds to a Gs-protein-coupled receptor on hepatocytes, activating adenylyl cyclase to produce cAMP, which activates protein kinase A (PKA). PKA phosphorylates and activates phosphorylase kinase and glycogen phosphorylase while inactivating glycogen synthase, promoting glycogenolysis. PKA also activates CREB to increase gluconeogenic enzyme transcription (PEPCK, G6Pase).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Metabolic Integration & Hormonal Control','medium','mcq','During prolonged fasting (greater than 48 hours), the brain adapts to use which fuel predominantly to spare muscle protein from gluconeogenic catabolism?','["A. Free fatty acids","B. Glycerol","C. Ketone bodies (acetoacetate and beta-hydroxybutyrate)","D. Lactate"]','C','After 48-72 hours of fasting, the brain increasingly uses ketone bodies (acetoacetate and beta-hydroxybutyrate) produced by the liver from fatty acid beta-oxidation. This glucose-sparing adaptation reduces the need for amino acid conversion to glucose (gluconeogenesis), protecting muscle protein. After prolonged starvation (weeks), ketone bodies can supply up to 70% of brain energy needs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Metabolic Integration & Hormonal Control','medium','mcq','AMP-activated protein kinase (AMPK) is activated by a high AMP/ATP ratio. Which of the following best describes the metabolic effects of AMPK activation?','["A. It activates acetyl-CoA carboxylase and HMG-CoA reductase, increasing fat and cholesterol synthesis","B. It inhibits catabolic pathways and activates anabolic pathways to restore energy","C. It promotes glycogen synthesis and lipogenesis to store excess energy","D. It activates fatty acid oxidation and inhibits fatty acid synthesis, cholesterol synthesis, and gluconeogenesis"]','D','AMPK is activated when AMP/ATP ratio rises (low energy state), signalling energy depletion. It phosphorylates and inactivates acetyl-CoA carboxylase (inhibiting fatty acid synthesis and activating CPT-I) and HMG-CoA reductase (inhibiting cholesterol synthesis), while activating fatty acid oxidation and glucose uptake. Metformin and exercise activate AMPK, making it a key diabetes drug target.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Metabolic Integration & Hormonal Control','hard','mcq','In type 1 diabetes mellitus, which metabolic scenario is responsible for the development of diabetic ketoacidosis (DKA)?','["A. Absolute insulin deficiency leads to uncontrolled lipolysis, excess acetyl-CoA, and ketone body overproduction","B. Excess insulin causes profound hypoglycaemia and ketosis","C. Glucagon deficiency impairs glycogenolysis","D. Excess cortisol causes insulin resistance and ketosis"]','A','In T1DM, absolute insulin deficiency removes the normal inhibition of hormone-sensitive lipase (HSL) in adipocytes, causing uncontrolled lipolysis and massive FFA release. The liver receives excess fatty acids and, with oxaloacetate depleted by gluconeogenesis, channels acetyl-CoA into ketogenesis, producing acetoacetate and beta-hydroxybutyrate faster than peripheral tissues can use them, causing metabolic acidosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Metabolic Integration & Hormonal Control','medium','mcq','During a 24-hour fast in a healthy adult, which organ serves as the primary source of blood glucose through glycogenolysis and gluconeogenesis?','["A. Skeletal muscle","B. Liver","C. Kidney","D. Adipose tissue"]','B','The liver is the primary organ maintaining blood glucose during fasting. In the early fasting state (6-24 hours), glycogenolysis from hepatic glycogen (approximately 80-100 g) provides glucose. As fasting extends and glycogen depletes, gluconeogenesis (from lactate via Cori cycle, alanine via glucose-alanine cycle, and glycerol from lipolysis) becomes predominant. Muscle lacks glucose-6-phosphatase so cannot export glucose.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Metabolic Integration & Hormonal Control','medium','mcq','Cortisol (a glucocorticoid) promotes gluconeogenesis by which molecular mechanism?','["A. It directly phosphorylates and activates pyruvate carboxylase","B. It activates glucagon release from the alpha cells of the pancreas","C. It increases transcription of PEPCK and other gluconeogenic enzymes via glucocorticoid response elements (GREs)","D. It directly inhibits insulin secretion from beta cells"]','C','Cortisol binds to the intracellular glucocorticoid receptor (GR); the GR-cortisol complex translocates to the nucleus and binds glucocorticoid response elements (GREs) in promoters of gluconeogenic genes, particularly PEPCK (phosphoenolpyruvate carboxykinase). This transcriptional activation increases gluconeogenic enzyme expression, raising blood glucose during stress. Prolonged glucocorticoid therapy causes secondary diabetes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Metabolic Integration & Hormonal Control','easy','mcq','The Cori cycle (glucose-lactate cycle) describes an important metabolic interplay between which two organs?','["A. Liver and adipose tissue","B. Liver and heart","C. Kidney and brain","D. Liver and exercising muscle or red blood cells"]','D','The Cori cycle operates between the liver and exercising muscle (or red blood cells). Exercising muscle and RBCs produce lactate from glucose via anaerobic glycolysis. Lactate is exported to the liver, where it is converted back to glucose by gluconeogenesis (via lactate dehydrogenase, pyruvate carboxylase, and PEPCK). This glucose is returned to the blood for muscle and RBC use, at a net cost of 4 ATP equivalents per cycle.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Metabolic Integration & Hormonal Control','hard','mcq','Which adipokine is secreted by adipose tissue in proportion to fat mass, acts on the hypothalamus to suppress appetite, and whose deficiency causes severe early-onset obesity?','["A. Leptin","B. Adiponectin","C. Ghrelin","D. Resistin"]','A','Leptin is secreted by adipocytes in proportion to fat mass and signals to hypothalamic neurons (particularly POMC/CART neurons) to suppress appetite by inhibiting the NPY/AgRP feeding circuit and increasing energy expenditure. Leptin deficiency or leptin receptor mutations (ob/ob mouse, db/db mouse) cause severe early-onset obesity. Most obese humans have leptin resistance, not leptin deficiency.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Metabolic Integration & Hormonal Control','medium','mcq','Metformin, the first-line oral drug for type 2 diabetes, primarily acts by which biochemical mechanism?','["A. It stimulates insulin secretion from pancreatic beta cells","B. It inhibits Complex I of the mitochondrial ETC in hepatocytes, raising AMP/ATP ratio, activating AMPK, and reducing hepatic gluconeogenesis","C. It competitively inhibits glucokinase in hepatocytes, reducing glucose phosphorylation","D. It blocks GLUT-2 in hepatocytes, reducing glucose uptake and glycogen synthesis"]','B','Metformin''s primary mechanism involves inhibition of Complex I of the mitochondrial ETC in hepatocytes, raising the AMP/ATP ratio and activating AMPK. AMPK phosphorylates and inactivates acetyl-CoA carboxylase and inhibits TORC2 (a coactivator of CREB), reducing expression of PEPCK and G6Pase, thereby decreasing hepatic gluconeogenesis. Metformin does not cause hypoglycaemia and is weight-neutral or causes modest weight loss.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Inborn Errors of Metabolism','easy','mcq','A newborn develops jaundice, cataracts, and liver disease after initiating milk feeding. Red cell galactose-1-phosphate is markedly elevated. Which enzyme is most likely deficient?','["A. Galactose-1-phosphate uridylyltransferase (GALT)","B. Galactokinase","C. UDP-galactose-4-epimerase","D. Aldose reductase"]','A','Classic galactosaemia is caused by deficiency of galactose-1-phosphate uridylyltransferase (GALT), causing accumulation of galactose-1-phosphate, which is toxic to liver, brain, and lens. Neonates present with jaundice, vomiting, Escherichia coli sepsis, cataracts (from galactitol accumulation in lens by aldose reductase), and liver failure. Treatment requires immediate elimination of galactose from diet.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Inborn Errors of Metabolism','medium','mcq','Pompe disease (GSD type II) results from deficiency of acid alpha-glucosidase, causing massive glycogen accumulation in which organelle?','["A. Mitochondria","B. Lysosomes","C. Smooth endoplasmic reticulum","D. Nucleus"]','B','Pompe disease is a lysosomal storage disease caused by deficiency of lysosomal acid alpha-glucosidase, which normally degrades glycogen within lysosomes. Glycogen accumulates in lysosomes of heart, skeletal muscle, and liver, causing hypertrophic cardiomyopathy, hypotonia, and respiratory failure in the classic infantile form. Enzyme replacement therapy with alglucosidase alfa (Myozyme) has transformed outcomes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Inborn Errors of Metabolism','medium','mcq','A 6-year-old with Gaucher disease has hepatosplenomegaly, bone marrow infiltration, and Gaucher cells (macrophages with crinkled-tissue-paper cytoplasm). Which enzyme is deficient?','["A. Sphingomyelinase","B. Hexosaminidase A","C. Glucocerebrosidase (acid beta-glucosidase)","D. Alpha-galactosidase A"]','C','Gaucher disease (the most common lysosomal storage disease) is caused by deficiency of glucocerebrosidase (acid beta-glucosidase), causing accumulation of glucocerebroside in lysosomes of macrophages in the liver, spleen, and bone marrow. The characteristic Gaucher cells have crinkled-tissue-paper cytoplasm. Type 1 (non-neuropathic) is most common; enzyme replacement therapy with imiglucerase is effective.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Inborn Errors of Metabolism','medium','mcq','Tay-Sachs disease is a fatal lysosomal storage disease in Ashkenazi Jewish children causing progressive neurodegeneration and a cherry-red spot on the macula. Which enzyme is deficient?','["A. Glucocerebrosidase","B. Beta-galactosidase","C. Sphingomyelinase","D. Hexosaminidase A (alpha subunit deficiency)"]','D','Tay-Sachs disease is caused by deficiency of the alpha subunit of hexosaminidase A, causing accumulation of GM2 ganglioside in neurons. Features include progressive neurodegeneration from 3-6 months, exaggerated startle response, cherry-red spot on the fovea (surrounding retinal ganglion cells appear white from lipid storage while the avascular fovea retains its colour), and death by age 2-5.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Inborn Errors of Metabolism','hard','mcq','Von Gierke disease (GSD type Ia) is characterised by severe fasting hypoglycaemia, hepatomegaly, lactic acidosis, and hyperlipidaemia. Which enzyme is deficient?','["A. Glucose-6-phosphatase","B. Glycogen phosphorylase","C. Debranching enzyme (amylo-1,6-glucosidase)","D. Glucokinase"]','A','Von Gierke disease (GSD type Ia) results from deficiency of glucose-6-phosphatase, required to release free glucose from glucose-6-phosphate into the blood. Since neither glycogenolysis nor gluconeogenesis can produce exportable glucose, severe fasting hypoglycaemia occurs. The liver accumulates massive glycogen and fat. Lactic acidosis occurs from G6P-driven glycolysis. Hyperlipidaemia and hyperuricaemia are also characteristic.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Inborn Errors of Metabolism','medium','mcq','Niemann-Pick disease Type A and Type B are both caused by acid sphingomyelinase deficiency. Which of the following correctly distinguishes the two types?','["A. Type A involves the liver only; Type B involves the nervous system only","B. Type A has severe neurological involvement with death in early childhood; Type B has predominantly visceral involvement without severe neurodegeneration","C. Type A is caused by sphingomyelinase deficiency; Type B is caused by NPC1 protein deficiency","D. Types A and B have identical clinical presentations differing only in age of onset"]','B','Niemann-Pick disease Types A and B are both caused by acid sphingomyelinase (SMPD1 gene) deficiency causing sphingomyelin accumulation in lysosomes. Type A (infantile, severe) has both visceral and severe CNS involvement with death by age 3. Type B (chronic, non-neuropathic) primarily affects visceral organs (spleen, liver, lungs) with little or no CNS disease and longer survival. Type C is a distinct disease due to NPC1 or NPC2 gene mutations.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Inborn Errors of Metabolism','medium','mcq','McArdle disease (GSD type V) is characterised by exercise intolerance, painful muscle cramps, and myoglobinuria on strenuous exertion. Which enzyme is deficient?','["A. Liver glycogen phosphorylase","B. Muscle phosphofructokinase-1","C. Muscle glycogen phosphorylase (myophosphorylase)","D. Muscle phosphoglycerate kinase"]','C','McArdle disease is caused by deficiency of muscle glycogen phosphorylase (myophosphorylase), preventing glycogenolysis in skeletal muscle. Patients cannot use muscle glycogen as energy during exercise, causing cramps, exercise intolerance, and myoglobinuria from rhabdomyolysis. A pathognomonic finding is the ischemic forearm exercise test: venous lactate fails to rise (cannot mobilize muscle glycogen) while ammonia rises normally.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Inborn Errors of Metabolism','easy','mcq','A patient with alkaptonuria has urine that turns dark on standing (due to oxidation of homogentisic acid), ochronosis (dark pigmentation of cartilage and connective tissue), and degenerative arthritis. Which enzyme is deficient?','["A. Tyrosine aminotransferase","B. 4-Hydroxyphenylpyruvate dioxygenase","C. Fumarylacetoacetate hydrolase","D. Homogentisate oxidase (homogentisic acid oxidase)"]','D','Alkaptonuria is caused by deficiency of homogentisate oxidase, causing accumulation of homogentisic acid, an intermediate in tyrosine catabolism. Homogentisic acid is excreted in urine (turning black on oxidation and alkalinisation) and deposited as a dark polymer in cartilage and connective tissue (ochronosis), leading to degenerative arthritis. Alkaptonuria was one of the first inborn errors of metabolism described by Garrod in 1902.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Inborn Errors of Metabolism','hard','mcq','Fabry disease is an X-linked lysosomal storage disease caused by deficiency of alpha-galactosidase A, leading to accumulation of which glycosphingolipid?','["A. Globotriaosylceramide (Gb3)","B. GM2 ganglioside","C. Glucocerebroside","D. Sphingomyelin"]','A','Fabry disease is caused by deficiency of alpha-galactosidase A (GLA gene, X-linked), causing accumulation of globotriaosylceramide (Gb3) in endothelial cells, cardiomyocytes, renal tubular cells, and neurons. Clinical features include angiokeratomas (skin lesions), acroparesthesias, anhidrosis, hypertrophic cardiomyopathy, progressive renal failure, and increased stroke risk. Enzyme replacement therapy with agalsidase alfa or beta is available.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Inborn Errors of Metabolism','medium','mcq','A neonate presents with hyperammonemia, elevated urinary orotic acid, and respiratory alkalosis. Which urea cycle defect is most consistent, and why is orotic acid elevated?','["A. CPS-I deficiency: excess carbamoyl phosphate is diverted to pyrimidine synthesis causing orotic aciduria","B. OTC deficiency: excess carbamoyl phosphate exits the mitochondria and enters cytoplasmic pyrimidine synthesis","C. Argininosuccinate lyase deficiency: excess argininosuccinate is converted to orotic acid","D. Arginase deficiency: excess arginine is catabolised to orotic acid"]','B','OTC (ornithine transcarbamylase) deficiency is the most common urea cycle disorder and is X-linked. When carbamoyl phosphate cannot be condensed with ornithine (due to OTC deficiency), it accumulates in the mitochondria and leaks into the cytoplasm, where it enters pyrimidine synthesis, producing excess orotic acid (orotic aciduria). CPS-I deficiency causes hyperammonemia WITHOUT elevated orotic acid (carbamoyl phosphate is not made).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
